import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { createHash, webcrypto } from "node:crypto";
import { describe, expect, it, vi } from "vitest";
import {
  readOnnxMetadata,
  inspectOnnxBytes,
} from "@/onnx/editor/onnx-metadata.js";
import { applyModelFacts, modelFacts } from "@/onnx/editor/model-facts.js";
import {
  createDefaultDocument,
  validateDocument,
} from "@/onnx/config/document.js";

// These tiny models were generated by official onnx.helper, independently of
// the browser parser; manifest hashes preserve their provenance from the demo.
const fixturePath = (name) =>
  resolve(process.cwd(), "test/onnx/fixtures/metadata", name);
const bytes = (name) =>
  new Uint8Array(readFileSync(fixturePath(`${name}.onnx`)));
const manifest = JSON.parse(
  readFileSync(fixturePath("manifest.json"), "utf8"),
).fixtures;
const pipeline = () => createDefaultDocument().task.pipeline;

describe("ONNX metadata and factual configuration", () => {
  it("reads independent ONNX IO and keeps metadata as text, including unsafe-looking keys", async () => {
    vi.stubGlobal("crypto", webcrypto);
    try {
      const buffer = bytes("static"),
        info = await inspectOnnxBytes(buffer);
      expect(info.bytes).toBe(manifest.static.bytes);
      expect(info.sha256).toBe(manifest.static.sha256);
      expect(info.sha256).toBe(
        createHash("sha256").update(buffer).digest("hex"),
      );
      expect(info.inputs).toEqual([
        { name: "pixels", type: "float32", shape: [1, 3, 8, 12] },
      ]);
      expect(info.outputs).toEqual([
        { name: "result", type: "float32", shape: [1, 3, 8, 12] },
      ]);
      expect(info.metadata.modelVersion).toBe("9223372036854775807");
      expect(info.metadata.properties).toContainEqual({
        key: "__proto__",
        value: "plain text",
      });
      expect(info.metadata.docString).toContain('system("must never execute")');
      expect(info.metadata.externalData).toBe(false);
    } finally {
      vi.unstubAllGlobals();
    }
  });

  it("distinguishes dynamic dimensions, missing rank, scalar and unsupported type", () => {
    expect(readOnnxMetadata(bytes("dynamic")).inputs[0].shape).toEqual([
      "batch",
      3,
      null,
      "width",
    ]);
    expect(readOnnxMetadata(bytes("unknown-rank")).inputs[0].shape).toBeNull();
    expect(readOnnxMetadata(bytes("scalar")).inputs[0].shape).toEqual([]);
    expect(readOnnxMetadata(bytes("uint8")).issues).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          code: "UNSUPPORTED_TYPE",
          direction: "input",
        }),
      ]),
    );
    expect(readOnnxMetadata(bytes("sequence")).inputs[0].type).toBe("sequence");
    expect(
      readOnnxMetadata(bytes("initializer-input")).inputs.map(
        (input) => input.name,
      ),
    ).toEqual(["pixels"]);
  });

  it.each([
    "external-initializer",
    "external-subgraph",
    "external-sparse",
    "external-function",
  ])("detects external weights in %s without reading their paths", (name) => {
    const info = readOnnxMetadata(bytes(name));
    expect(info.metadata.externalData).toBe(true);
    expect(info.metadata.externalDataLocations.length).toBeGreaterThan(0);
    expect(info.issues).toContainEqual(
      expect.objectContaining({ code: "EXTERNAL_DATA" }),
    );
    expect(modelFacts(info, pipeline()).error).toContain("外置权重");
  });

  it("only sets dimensions supported by a unique channel-axis interpretation", () => {
    const info = readOnnxMetadata(bytes("static")),
      config = pipeline();
    const before = {
      color: config.input.color,
      scale: config.input.scale,
      mean: [...config.input.mean],
      std: [...config.input.std],
    };
    applyModelFacts(info, config);
    expect(config.input).toMatchObject({
      name: "pixels",
      width: 12,
      height: 8,
      layout: "NCHW",
      ...before,
    });
    const ambiguous = readOnnxMetadata(bytes("dynamic"));
    expect(modelFacts(ambiguous, config).autoLayout).toBeNull();
    ambiguous.inputs[0].shape = [1, 3, 224, "channels"];
    expect(modelFacts(ambiguous, config).autoLayout).toBeNull();
    ambiguous.inputs[0].shape = [1, 3, 0, 224];
    expect(modelFacts(ambiguous, config).error).toContain("非正数");
  });

  it("rejects invalid/truncated model bytes with a distinguishable parser error", () => {
    const valid = bytes("static");
    for (const value of [
      new Uint8Array(),
      valid.slice(0, 12),
      new Uint8Array([0xff, 0xff]),
    ])
      expect(() => readOnnxMetadata(value)).toThrow(
        expect.objectContaining({ code: "INVALID_ONNX" }),
      );
  });

  it("refuses executable rule hooks and unregistered components at the imported JSON boundary", () => {
    const hooked = createDefaultDocument();
    hooked.ui.rules[0].on = { click: "$FN:window.evil()" };
    expect(() =>
      validateDocument(JSON.parse(JSON.stringify(hooked))),
    ).toThrow();
    const component = createDefaultDocument();
    component.ui.rules.push({
      type: "html",
      props: { innerHTML: '<img src="bad" onerror="window.evil()">' },
    });
    expect(() =>
      validateDocument(JSON.parse(JSON.stringify(component))),
    ).toThrow();
    const polluted = JSON.parse(JSON.stringify(createDefaultDocument()));
    Object.defineProperty(polluted.ui.options, "__proto__", {
      value: { unexpected: true },
      enumerable: true,
    });
    expect(() => validateDocument(polluted)).toThrow();
    expect({}.unexpected).toBeUndefined();
  });
});
